@page "/settings"
@using sv_dc22b0e17d6144239b89e07bab6b1755.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => ActiveSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => ActiveSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => ActiveSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => ActiveSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @switch (ActiveSection)
        {
            case "Profile":
                <section class="settings-section">
                    <h2>Profile Settings</h2>
                    @if (_profile is not null)
                    {
                        <div class="form-group avatar-group">
                            <label>Avatar</label>
                            <div class="avatar-preview">
                                <img src="@_editDisplayName" alt="Avatar" style="display:none;" />
                                <div class="avatar-placeholder">
                                    <img src="@_editAvatarUrl" alt="Avatar" class="avatar-img" />
                                </div>
                                <span class="avatar-url">@_editAvatarUrl</span>
                            </div>
                        </div>
                        <div class="form-group">
                            <label for="displayName">Display Name</label>
                            <input id="displayName" type="text" @bind="_editDisplayName" />
                        </div>
                        <div class="form-group">
                            <label for="email">Email</label>
                            <input id="email" type="email" @bind="_editEmail" />
                        </div>
                        <div class="form-group">
                            <label for="bio">Bio</label>
                            <textarea id="bio" rows="4" @bind="_editBio"></textarea>
                        </div>
                        <div class="form-group">
                            <label for="avatarUrl">Avatar URL</label>
                            <input id="avatarUrl" type="url" @bind="_editAvatarUrl" />
                        </div>
                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    }
                </section>
                break;

            case "Notifications":
                <section class="settings-section">
                    <h2>Notification Preferences</h2>
                    @if (_notificationPrefs is not null)
                    {
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editEmailNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editPushNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editWeeklyDigest" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channel-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editMutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                    <span>#@channel</span>
                                </label>
                            }
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    }
                </section>
                break;

            case "Security":
                <section class="settings-section">
                    <h2>Security Settings</h2>
                    @if (_security is not null)
                    {
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                                <span>Change Password</span>
                                <span class="panel-toggle">@(_passwordPanelOpen ? "▾" : "▸")</span>
                            </button>
                            @if (_passwordPanelOpen)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group" style="margin-top: 1.5rem;">
                            <label class="toggle-label">
                                <span>
                                    Two-Factor Authentication
                                    <span class="status-indicator @(_editTwoFactorEnabled ? "status-on" : "status-off")">
                                        @(_editTwoFactorEnabled ? "Enabled" : "Disabled")
                                    </span>
                                </span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editTwoFactorEnabled" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        @if (_security.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _security.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == _security.Sessions.First().Id)
                                            {
                                                <span class="current-session">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>

                        @if (_showRevokeConfirmation && _sessionToRevoke is not null)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal" @onclick:stopPropagation="true">
                                    <h3>Revoke Session</h3>
                                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                    <div class="button-group">
                                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    }
                </section>
                break;

            case "Appearance":
                <section class="settings-section">
                    <h2>Appearance Settings</h2>
                    @if (_appearance is not null)
                    {
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light" @onchange='() => _editTheme = "Light"' checked="@(_editTheme == "Light")" />
                                    <span>Light</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark" @onchange='() => _editTheme = "Dark"' checked="@(_editTheme == "Dark")" />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System" @onchange='() => _editTheme = "System"' checked="@(_editTheme == "System")" />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small" @onchange='() => _editFontSize = "Small"' checked="@(_editFontSize == "Small")" />
                                    <span>Small</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium" @onchange='() => _editFontSize = "Medium"' checked="@(_editFontSize == "Medium")" />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large" @onchange='() => _editFontSize = "Large"' checked="@(_editFontSize == "Large")" />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editCompactMode" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Live Preview</h3>
                        <div class="appearance-preview @GetPreviewClasses()">
                            <div class="preview-header">Preview Area</div>
                            <p class="preview-text">This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Theme: @_editTheme | Font: @_editFontSize | Compact: @(_editCompactMode ? "On" : "Off")</p>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    }
                </section>
                break;
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "toast-success";

    // Profile state
    private UserProfile? _profile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = new();
    private List<string> _allChannels = new();

    // Security state
    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _editTwoFactorEnabled;
    private bool _showRevokeConfirmation;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private AppearanceSettings? _appearance;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    // Profile methods
    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        ResetProfileFields();
    }

    private void ResetProfileFields()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editBio = _profile.Bio;
        _editAvatarUrl = _profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "toast-info");
    }

    // Notifications methods
    private async Task LoadNotifications()
    {
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editEmailNotifications = _notificationPrefs.EmailNotifications;
        _editPushNotifications = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _editMutedChannels = new List<string>(_notificationPrefs.MutedChannels);
        _allChannels = new List<string>(_notificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!isMuted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, new List<string>(_editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        _editTwoFactorEnabled = _security.TwoFactorEnabled;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "toast-error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
        await LoadSecurity();
        ShowToast("Session revoked.", "toast-success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        _appearance = await SettingsService.GetAppearanceAsync();
        _editTheme = _appearance.Theme;
        _editFontSize = _appearance.FontSize;
        _editLanguage = _appearance.Language;
        _editCompactMode = _appearance.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_editTheme.ToLowerInvariant()} preview-font-{_editFontSize.ToLowerInvariant()}";
        if (_editCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        ShowToast("Appearance settings saved!", "toast-success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ToastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        ToastMessage = null;
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 2rem;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1rem;
    cursor: pointer;
    border-radius: 8px;
    margin-bottom: 0.25rem;
    transition: background-color 0.2s, color 0.2s;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 500;
    color: #4b5563;
}

.settings-sidebar li:hover {
    background-color: #f3f4f6;
}

.settings-sidebar li.active {
    background-color: #3b82f6;
    color: white;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #1f2937;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    color: #374151;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.form-group textarea {
    resize: vertical;
}

/* Avatar */
.avatar-group .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e5e7eb;
}

.avatar-url {
    font-size: 0.8rem;
    color: #6b7280;
    word-break: break-all;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
    transform: scale(0.98);
}

.btn-primary {
    background-color: #3b82f6;
    color: white;
}

.btn-primary:hover {
    background-color: #2563eb;
}

.btn-secondary {
    background-color: #e5e7eb;
    color: #374151;
}

.btn-secondary:hover {
    background-color: #d1d5db;
}

.btn-danger {
    background-color: #ef4444;
    color: white;
}

.btn-danger:hover {
    background-color: #dc2626;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 400px;
    padding: 0.5rem 0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #d1d5db;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #3b82f6;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    max-width: 400px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0.5rem;
    border-radius: 4px;
    cursor: pointer;
}

.channel-item:hover {
    background-color: #f3f4f6;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: #f9fafb;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #374151;
}

.panel-header:hover {
    background: #f3f4f6;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e5e7eb;
}

/* Status indicator */
.status-indicator {
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    margin-left: 0.5rem;
}

.status-on {
    background-color: #d1fae5;
    color: #065f46;
}

.status-off {
    background-color: #fee2e2;
    color: #991b1b;
}

.info-text {
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e5e7eb;
}

.sessions-table th {
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #6b7280;
    font-weight: 600;
}

.current-session {
    font-size: 0.8rem;
    color: #059669;
    font-weight: 500;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.5rem;
    max-width: 500px;
    transition: all 0.3s;
}

.appearance-preview .preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.appearance-preview .preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
}

/* Theme previews */
.preview-theme-light {
    background-color: #ffffff;
    color: #1f2937;
}

.preview-theme-dark {
    background-color: #1f2937;
    color: #f9fafb;
    border-color: #374151;
}

.preview-theme-dark .preview-card {
    border-color: #4b5563;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1f2937 50%);
    color: #1f2937;
}

/* Font size previews */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.2;
}

.preview-compact .preview-card {
    padding: 0.4rem;
    margin-top: 0.4rem;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal h3 {
    margin-top: 0;
}

/* Toast */
.toast {
    padding: 0.75rem 1rem;
    border-radius: 8px;
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background-color: #d1fae5;
    color: #065f46;
    border: 1px solid #6ee7b7;
}

.toast-error {
    background-color: #fee2e2;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

.toast-info {
    background-color: #dbeafe;
    color: #1e40af;
    border: 1px solid #93c5fd;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.7;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@page "/settings"
@using sv_dc22b0e17d6144239b89e07bab6b1755.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => ActiveSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => ActiveSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => ActiveSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => ActiveSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @switch (ActiveSection)
        {
            case "Profile":
                <section class="settings-section">
                    <h2>Profile Settings</h2>
                    @if (_profile is not null)
                    {
                        <div class="form-group avatar-group">
                            <label>Avatar</label>
                            <div class="avatar-preview">
                                <img src="@_editDisplayName" alt="Avatar" style="display:none;" />
                                <div class="avatar-placeholder">
                                    <img src="@_editAvatarUrl" alt="Avatar" class="avatar-img" />
                                </div>
                                <span class="avatar-url">@_editAvatarUrl</span>
                            </div>
                        </div>
                        <div class="form-group">
                            <label for="displayName">Display Name</label>
                            <input id="displayName" type="text" @bind="_editDisplayName" />
                        </div>
                        <div class="form-group">
                            <label for="email">Email</label>
                            <input id="email" type="email" @bind="_editEmail" />
                        </div>
                        <div class="form-group">
                            <label for="bio">Bio</label>
                            <textarea id="bio" rows="4" @bind="_editBio"></textarea>
                        </div>
                        <div class="form-group">
                            <label for="avatarUrl">Avatar URL</label>
                            <input id="avatarUrl" type="url" @bind="_editAvatarUrl" />
                        </div>
                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    }
                </section>
                break;

            case "Notifications":
                <section class="settings-section">
                    <h2>Notification Preferences</h2>
                    @if (_notificationPrefs is not null)
                    {
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editEmailNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editPushNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editWeeklyDigest" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channel-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editMutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                    <span>#@channel</span>
                                </label>
                            }
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    }
                </section>
                break;

            case "Security":
                <section class="settings-section">
                    <h2>Security Settings</h2>
                    @if (_security is not null)
                    {
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                                <span>Change Password</span>
                                <span class="panel-toggle">@(_passwordPanelOpen ? "▾" : "▸")</span>
                            </button>
                            @if (_passwordPanelOpen)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group" style="margin-top: 1.5rem;">
                            <label class="toggle-label">
                                <span>
                                    Two-Factor Authentication
                                    <span class="status-indicator @(_editTwoFactorEnabled ? "status-on" : "status-off")">
                                        @(_editTwoFactorEnabled ? "Enabled" : "Disabled")
                                    </span>
                                </span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editTwoFactorEnabled" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        @if (_security.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _security.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == _security.Sessions.First().Id)
                                            {
                                                <span class="current-session">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>

                        @if (_showRevokeConfirmation && _sessionToRevoke is not null)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal" @onclick:stopPropagation="true">
                                    <h3>Revoke Session</h3>
                                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                    <div class="button-group">
                                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    }
                </section>
                break;

            case "Appearance":
                <section class="settings-section">
                    <h2>Appearance Settings</h2>
                    @if (_appearance is not null)
                    {
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light" @onchange='() => _editTheme = "Light"' checked="@(_editTheme == "Light")" />
                                    <span>Light</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark" @onchange='() => _editTheme = "Dark"' checked="@(_editTheme == "Dark")" />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System" @onchange='() => _editTheme = "System"' checked="@(_editTheme == "System")" />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small" @onchange='() => _editFontSize = "Small"' checked="@(_editFontSize == "Small")" />
                                    <span>Small</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium" @onchange='() => _editFontSize = "Medium"' checked="@(_editFontSize == "Medium")" />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large" @onchange='() => _editFontSize = "Large"' checked="@(_editFontSize == "Large")" />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editCompactMode" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Live Preview</h3>
                        <div class="appearance-preview @GetPreviewClasses()">
                            <div class="preview-header">Preview Area</div>
                            <p class="preview-text">This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Theme: @_editTheme | Font: @_editFontSize | Compact: @(_editCompactMode ? "On" : "Off")</p>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    }
                </section>
                break;
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "toast-success";

    // Profile state
    private UserProfile? _profile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = new();
    private List<string> _allChannels = new();

    // Security state
    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _editTwoFactorEnabled;
    private bool _showRevokeConfirmation;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private AppearanceSettings? _appearance;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    // Profile methods
    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        ResetProfileFields();
    }

    private void ResetProfileFields()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editBio = _profile.Bio;
        _editAvatarUrl = _profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "toast-info");
    }

    // Notifications methods
    private async Task LoadNotifications()
    {
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editEmailNotifications = _notificationPrefs.EmailNotifications;
        _editPushNotifications = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _editMutedChannels = new List<string>(_notificationPrefs.MutedChannels);
        _allChannels = new List<string>(_notificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!isMuted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, new List<string>(_editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        _editTwoFactorEnabled = _security.TwoFactorEnabled;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "toast-error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
        await LoadSecurity();
        ShowToast("Session revoked.", "toast-success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        _appearance = await SettingsService.GetAppearanceAsync();
        _editTheme = _appearance.Theme;
        _editFontSize = _appearance.FontSize;
        _editLanguage = _appearance.Language;
        _editCompactMode = _appearance.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_editTheme.ToLowerInvariant()} preview-font-{_editFontSize.ToLowerInvariant()}";
        if (_editCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        ShowToast("Appearance settings saved!", "toast-success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ToastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        ToastMessage = null;
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 2rem;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1rem;
    cursor: pointer;
    border-radius: 8px;
    margin-bottom: 0.25rem;
    transition: background-color 0.2s, color 0.2s;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 500;
    color: #4b5563;
}

.settings-sidebar li:hover {
    background-color: #f3f4f6;
}

.settings-sidebar li.active {
    background-color: #3b82f6;
    color: white;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #1f2937;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    color: #374151;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.form-group textarea {
    resize: vertical;
}

/* Avatar */
.avatar-group .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e5e7eb;
}

.avatar-url {
    font-size: 0.8rem;
    color: #6b7280;
    word-break: break-all;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
    transform: scale(0.98);
}

.btn-primary {
    background-color: #3b82f6;
    color: white;
}

.btn-primary:hover {
    background-color: #2563eb;
}

.btn-secondary {
    background-color: #e5e7eb;
    color: #374151;
}

.btn-secondary:hover {
    background-color: #d1d5db;
}

.btn-danger {
    background-color: #ef4444;
    color: white;
}

.btn-danger:hover {
    background-color: #dc2626;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 400px;
    padding: 0.5rem 0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #d1d5db;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #3b82f6;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    max-width: 400px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0.5rem;
    border-radius: 4px;
    cursor: pointer;
}

.channel-item:hover {
    background-color: #f3f4f6;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: #f9fafb;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #374151;
}

.panel-header:hover {
    background: #f3f4f6;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e5e7eb;
}

/* Status indicator */
.status-indicator {
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    margin-left: 0.5rem;
}

.status-on {
    background-color: #d1fae5;
    color: #065f46;
}

.status-off {
    background-color: #fee2e2;
    color: #991b1b;
}

.info-text {
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e5e7eb;
}

.sessions-table th {
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #6b7280;
    font-weight: 600;
}

.current-session {
    font-size: 0.8rem;
    color: #059669;
    font-weight: 500;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.5rem;
    max-width: 500px;
    transition: all 0.3s;
}

.appearance-preview .preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.appearance-preview .preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
}

/* Theme previews */
.preview-theme-light {
    background-color: #ffffff;
    color: #1f2937;
}

.preview-theme-dark {
    background-color: #1f2937;
    color: #f9fafb;
    border-color: #374151;
}

.preview-theme-dark .preview-card {
    border-color: #4b5563;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1f2937 50%);
    color: #1f2937;
}

/* Font size previews */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.2;
}

.preview-compact .preview-card {
    padding: 0.4rem;
    margin-top: 0.4rem;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal h3 {
    margin-top: 0;
}

/* Toast */
.toast {
    padding: 0.75rem 1rem;
    border-radius: 8px;
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background-color: #d1fae5;
    color: #065f46;
    border: 1px solid #6ee7b7;
}

.toast-error {
    background-color: #fee2e2;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

.toast-info {
    background-color: #dbeafe;
    color: #1e40af;
    border: 1px solid #93c5fd;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.7;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

