{"file_text": "@page "/settings"
@using sv_dc22b0e17d6144239b89e07bab6b1755.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => ActiveSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => ActiveSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => ActiveSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => ActiveSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @switch (ActiveSection)
        {
            case "Profile":
                <section class="settings-section">
                    <h2>Profile Settings</h2>
                    @if (_profile is not null)
                    {
                        <div class="form-group avatar-group">
                            <label>Avatar</label>
                            <div class="avatar-preview">
                                <img src="@_editDisplayName" alt="Avatar" style="display:none;" />
                                <div class="avatar-placeholder">
                                    <img src="@_editAvatarUrl" alt="Avatar" class="avatar-img" />
                                </div>
                                <span class="avatar-url">@_editAvatarUrl</span>
                            </div>
                        </div>
                        <div class="form-group">
                            <label for="displayName">Display Name</label>
                            <input id="displayName" type="text" @bind="_editDisplayName" />
                        </div>
                        <div class="form-group">
                            <label for="email">Email</label>
                            <input id="email" type="email" @bind="_editEmail" />
                        </div>
                        <div class="form-group">
                            <label for="bio">Bio</label>
                            <textarea id="bio" rows="4" @bind="_editBio"></textarea>
                        </div>
                        <div class="form-group">
                            <label for="avatarUrl">Avatar URL</label>
                            <input id="avatarUrl" type="url" @bind="_editAvatarUrl" />
                        </div>
                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    }
                </section>
                break;

            case "Notifications":
                <section class="settings-section">
                    <h2>Notification Preferences</h2>
                    @if (_notificationPrefs is not null)
                    {
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editEmailNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editPushNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editWeeklyDigest" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channel-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editMutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                    <span>#@channel</span>
                                </label>
                            }
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    }
                </section>
                break;

            case "Security":
                <section class="settings-section">
                    <h2>Security Settings</h2>
                    @if (_security is not null)
                    {
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                                <span>Change Password</span>
                                <span class="panel-toggle">@(_passwordPanelOpen ? "▾" : "▸")</span>
                            </button>
                            @if (_passwordPanelOpen)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group" style="margin-top: 1.5rem;">
                            <label class="toggle-label">
                                <span>
                                    Two-Factor Authentication
                                    <span class="status-indicator @(_editTwoFactorEnabled ? "status-on" : "status-off")">
                                        @(_editTwoFactorEnabled ? "Enabled" : "Disabled")
                                    </span>
                                </span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editTwoFactorEnabled" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        @if (_security.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _security.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == _security.Sessions.First().Id)
                                            {
                                                <span class="current-session">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>

                        @if (_showRevokeConfirmation && _sessionToRevoke is not null)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal" @onclick:stopPropagation="true">
                                    <h3>Revoke Session</h3>
                                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                    <div class="button-group">
                                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    }
                </section>
                break;

            case "Appearance":
                <section class="settings-section">
                    <h2>Appearance Settings</h2>
                    @if (_appearance is not null)
                    {
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light" @onchange='() => _editTheme = "Light"' checked="@(_editTheme == "Light")" />
                                    <span>Light</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark" @onchange='() => _editTheme = "Dark"' checked="@(_editTheme == "Dark")" />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System" @onchange='() => _editTheme = "System"' checked="@(_editTheme == "System")" />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small" @onchange='() => _editFontSize = "Small"' checked="@(_editFontSize == "Small")" />
                                    <span>Small</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium" @onchange='() => _editFontSize = "Medium"' checked="@(_editFontSize == "Medium")" />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large" @onchange='() => _editFontSize = "Large"' checked="@(_editFontSize == "Large")" />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="_editCompactMode" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Live Preview</h3>
                        <div class="appearance-preview @GetPreviewClasses()">
                            <div class="preview-header">Preview Area</div>
                            <p class="preview-text">This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Theme: @_editTheme | Font: @_editFontSize | Compact: @(_editCompactMode ? "On" : "Off")</p>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    }
                </section>
                break;
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
